select pr.pr_id, pr.display_number, s.name as supplier, CONCAT_WS(' ', u.last_name, u.first_name) as requester, pr.due_date, pr.total_amount, pr.status from purchase_request pr join supplier s on pr.supplier_id = s.supplier_id join users u on pr.requester_user_id = u.user_id
s.supplier_id = #{supplierId}
and pr.due_date >= #{dueDateFrom}
and pr.due_date <= #{dueDateTo}
and pr.status = #{status}
and ( pr.display_number::varchar ~ #{keywordRegex} or normalization(lower(concat(u.last_name, u.first_name))) ~#{keywordRegex} or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{keywordRegex} )
order by
pr.display_number s.name concat(u.last_name_kana, u.first_name_kana) pr.due_date
asc nulls first desc nulls last
pr.total_amount
case pr.status when 'PENDING' then 1 when 'APPROVED' then 2 when 'REJECTED' then 3 when 'COMPLETED' then 4 end
asc desc
limit #{size} offset #{offset}

select count(*)
from purchase_request pr
join supplier s
  on pr.supplier_id = s.supplier_id
join users u
  on pr.requester_user_id = u.user_id


    s.supplier_id = #{supplierId}


    and pr.due_date >= #{dueDateFrom}


    and pr.due_date <= #{dueDateTo}


    and pr.status = #{status}



    and ( 
      pr.display_number::varchar ~ #{keywordRegex}
      or normalization(lower(concat(u.last_name, u.first_name))) ~#{keywordRegex}
      or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{keywordRegex}
    )
